INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q782474', 'Chadian Civil War of 1965–1979', 'The Chadian Civil War of 1965–1979 (French: Guerre civile tchadienne de 1965–1979) was waged by several rebel factions against two Chadian governments. The initial rebellion erupted in opposition to Chadian President François Tombalbaye, whose regime was marked by authoritarianism, extreme corruption, and favoritism.', 1965, 11, 1, 1979, NULL, NULL, 'day', '1 November 1965 – 1979', 50, 'https://en.wikipedia.org/wiki/Chadian_Civil_War_(1965%E2%80%931979)'),
  ('Q4271747', 'Chadian coup of 1975', 'On 13 April 1975, a military coup d''état deposed and killed Chadian president François Tombalbaye, replacing him by a military council. The most important factor leading up to the coup was a growing sentiment of distrust towards Tombalbaye inside the Chadian army.', 1975, 4, NULL, 1975, 4, 15, 'month', 'April 1975 – 15 April 1975', 37, 'https://en.wikipedia.org/wiki/1975_Chadian_coup_d''%C3%A9tat'),
  ('Q611071', 'Chadian–Libyan War', 'The Chadian–Libyan War was a series of military campaigns in Chad between 1978 and 1987, fought between Libya and its Chadian allies, and anti-Libyan Chadian groups supported by France, with the occasional involvement of other foreign countries and factions. Libya had been involved in Chad''s internal affairs prior to 1978 and before Muammar Gaddafi''s rise to power in Libya in 1969, beginning with the extension of the Chadian Civil War to northern Chad in 1968.', 1987, 9, 11, 1987, NULL, NULL, 'day', '1987', 64, 'https://en.wikipedia.org/wiki/Chadian%E2%80%93Libyan_War'),
  ('Q2502062', 'Battle of Fada', 'The Battle of Fada took place in northern Chad in 1987, and was a turning point of the Chadian–Libyan conflict.', 1987, 1, 2, NULL, NULL, NULL, 'day', '2 January 1987', 39, 'https://en.wikipedia.org/wiki/Battle_of_Fada'),
  ('Q65047871', '1990 Chadian coup d''état', 'The 1990 Chadian coup d''état took place on 1 December 1990 when the forces of the Patriotic Salvation Movement (MPS), a Libyan–backed rebel group under the leadership of General Idriss Déby, entered the Chadian capital N''Djamena unopposed. The MPS troops entered Chad by crossing the Sudanese border three weeks earlier.', 1990, 12, 3, NULL, NULL, NULL, 'day', '3 December 1990', 37, 'https://en.wikipedia.org/wiki/1990_Chadian_coup_d''%C3%A9tat'),
  ('Q75756', 'Second Congo War', 'The Second Congo War, also known as Africa''s World War or the Great War of Africa, was a major conflict that began on 2 August 1998 in the Democratic Republic of the Congo (DRC), just over a year after the First Congo War. The war initially erupted when Congolese president Laurent-Désiré Kabila turned against his former allies from Rwanda and Uganda, who had helped him seize power.', 1998, 8, 2, 2003, 6, 30, 'day', '2 August 1998 – 30 June 2003', 75, 'https://en.wikipedia.org/wiki/Second_Congo_War'),
  ('Q1021172', 'Republic of the Congo civil war', 'The Second Republic of the Congo Civil War, also known as the Second Brazzaville-Congolese Civil War, was the second of two ethnopolitical civil conflicts in the Republic of the Congo which lasted from 5 June 1997 to 29 December 1999. The war served as the continuation of the civil war of 1993–1994 and involved militias representing three political candidates.', 1999, 12, 29, 1999, NULL, NULL, 'day', '1999', 52, 'https://en.wikipedia.org/wiki/Republic_of_the_Congo_Civil_War_(1997%E2%80%931999)'),
  ('Q632787', 'Insurgency in the Maghreb', 'An Islamist insurgency is taking place in the Maghreb region of North Africa, followed on from the end of the Algerian Civil War in 2002. The Algerian militant group Salafist Group for Preaching and Combat (GSPC) allied itself with al-Qaeda to eventually become al-Qaeda in the Islamic Maghreb (AQIM).', 2002, 4, 11, NULL, NULL, NULL, 'day', '11 April 2002', 58, 'https://en.wikipedia.org/wiki/Insurgency_in_the_Maghreb_(2002%E2%80%93present)'),
  ('Q945700', 'Chad–Sudan Conflict', 'The Chadian Civil War of 2005–2010 began on 18 December 2005. Since its independence from France in 1960, Chad has been swamped by civil wars between the Arab-Muslims of the north and the Sub-Saharan-Christians of the south.', 2005, 12, 18, 2010, 1, 15, 'day', '18 December 2005 – 15 January 2010', 56, 'https://en.wikipedia.org/wiki/Chadian_Civil_War_(2005%E2%80%932010)'),
  ('Q2887811', 'Battle of Adré', 'The Battle of Adré took place in Adré, Chad on 18 December 2005. The battle began when the Chadian rebel groups Rally for Democracy and Liberty (RDL) and Platform for Change, Unity, and Democracy (SCUD), allegedly backed by the government of Sudan, attacked the garrison in this city.', 2005, 12, 18, NULL, NULL, NULL, 'day', '18 December 2005', 37, 'https://en.wikipedia.org/wiki/Battle_of_Adr%C3%A9'),
  ('Q2889481', 'Battle of N''Djamena', 'The Battle of N''Djamena took place between the forces of the revolutionary United Front for Democratic Change (UFCD) and the military of Chad that occurred on 13 April 2006 when rebel forces launched an assault on the capital of Chad in the pre-dawn hours, attempting to overthrow the government of President Idriss Déby Itno from their bases an estimated thousand miles east. The battle occurred just months after serious Chad-Sudan tensions ended with the signing of the Tripoli Agreement.', 2006, 4, 13, NULL, NULL, NULL, 'day', '13 April 2006', 39, 'https://en.wikipedia.org/wiki/Battle_of_N''Djamena_(2006)'),
  ('Q4607213', '2006 Zakouma elephant slaughter', 'The 2006 Zakouma elephant slaughter refers to a series of poaching massacres of African elephants in the vicinity of Zakouma National Park in southeastern Chad. These killings were documented in aerial surveys conducted from May through August 2006 and total at least 100 animals.', 2006, NULL, NULL, NULL, NULL, NULL, 'year', '2006', 41, 'https://en.wikipedia.org/wiki/2006_Zakouma_elephant_slaughter'),
  ('Q2889305', 'Battle of N''Djamena', 'The Battle of N''Djamena began on February 2, 2008, when Chadian rebel forces opposed to Chadian President Idriss Déby entered N''Djamena, the capital of Chad, after a three-day advance through the country. The rebels were initially successful, taking a large part of the city and attacking the heavily defended presidential palace.', 2008, NULL, NULL, 2008, 2, 4, 'year', '2008', 39, 'https://en.wikipedia.org/wiki/Battle_of_N''Djamena_(2008)'),
  ('Q4870285', 'Battle of Am Zoer', 'The Battle of Am Zoer occurred on June 18, 2008 when the Chadian army caught up with a rebel column that had been advancing towards the capital, N''Djamena. Sudanese forces were reported to have attacked Chadian positions on the border in previous days and the rebels had been seen passing through several eastern villages.', 2008, 6, 18, NULL, NULL, NULL, 'day', '18 June 2008', 34, 'https://en.wikipedia.org/wiki/Battle_of_Am_Zoer'),
  ('Q2887839', 'Battle of Am Dam', 'The Battle of Am Dam took place in and around the eastern Chadian town of Am Dam on May 7 and May 8, 2009 when Chadian Army forces attacked a column of advancing Union of Forces for the Resistance (UFR) rebels.', 2009, 5, 7, NULL, NULL, NULL, 'day', '7 May 2009', 39, 'https://en.wikipedia.org/wiki/Battle_of_Am_Dam'),
  ('Q106575438', 'Insurgency in Northern Chad', 'In 2016, the Front for Change and Concord in Chad (FACT) and the Military Command Council for the Salvation of the Republic (CCMSR) began a rebellion against the Chadian government. From their rear bases in southern Libya, FACT and CCMSR have launched offensives and raids into Northern Chad seeking to overthrow the government of former president Idriss Déby, who had been in power since a December 1990 coup.', 2016, NULL, NULL, NULL, NULL, NULL, 'year', '2016', 45, 'https://en.wikipedia.org/wiki/Insurgency_in_Chad_(2016%E2%80%93present)'),
  ('Q104856693', '2020 African Sahel floods', 'In all of 2020, flooding affected 2.7 million people in 18 countries in West and Central Africa and destroyed 197,000 houses, with many regions recording excess rainfalls. The number of flood-affected people this year was more than twice the case in 2019.', 2020, 8, NULL, 2020, 9, NULL, 'month', 'August 2020 – September 2020', 37, 'https://en.wikipedia.org/wiki/2020_African_Sahel_floods'),
  ('Q114006523', '2022 Chad floods', 'The 2022 Chadian floods began in the Republic of Chad during July 2022 and currently continued till September 2022 following the heaviest rains in the country since 1990. An estimated 442,000 Chadians had been affected or displaced by flooding by the end of August 2022, including in large parts of the national capital, N''Djamena.', 2022, NULL, NULL, NULL, NULL, NULL, 'year', '2022', 37, 'https://en.wikipedia.org/wiki/2022_Chad_floods'),
  ('Q126961247', '2024 West African floods', 'In 2024, heavy rainfall impacted several countries across West and Central Africa, including Nigeria, Chad, Niger, Mali, Guinea, Cameroon and Ghana. At least 1,500 were killed and more than a million were displaced.', 2024, NULL, NULL, NULL, NULL, NULL, 'year', '2024', 37, 'https://en.wikipedia.org/wiki/2024_West_African_floods'),
  ('Q131725511', '2025 N''Djamena attack', 'On 8 January 2025, an attack was carried out against the presidential palace, known as the Pink Palace, in the Chadian capital N''Djamena by unknown attackers. The 24 attackers attempted to gain entry through a security gate of the presidential palace before being confronted by security forces.', 2025, 1, 8, NULL, NULL, NULL, 'day', '8 January 2025', 50, 'https://en.wikipedia.org/wiki/2025_N''Djamena_attack');
